           VerifyOffsetRequired(verifier, VT_CATEGORIES) &&
           verifier.VerifyVector(CATEGORIES()) &&
           verifier.VerifyVectorOfTables(CATEGORIES()) &&
           VerifyOffset(verifier, VT_ROLLUPS) &&
           verifier.VerifyVector(ROLLUPS()) &&
           verifier.VerifyVectorOfTables(ROLLUPS()) &&
           VerifyOffset(verifier, VT_SIGNATURE) &&
           verifier.VerifyVector(SIGNATURE()) &&
           verifier.EndTable();
