  CCTT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(CCTT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<CCT> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const CCTT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
